cat > src/lib/selection.ts <<'EOF'
// Image selection caps: max 2 landscape, 1 portrait (fixed requirement)
const MAX_LANDSCAPE = 2;
const MAX_PORTRAIT = 1;

export function canAdd(selected: {portrait: boolean}[], next: {portrait: boolean}): boolean {
  const portraits = selected.filter(s => s.portrait).length;
  const landscapes = selected.length - portraits;
  if (next.portrait) return portraits < MAX_PORTRAIT;
  return landscapes < MAX_LANDSCAPE;
}
EOF
cat > tests/selection.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert';
import { readFileSync } from 'node:fs';

// selection.ts is TypeScript; strip types minimally by loading it via data URL.
const src = readFileSync(new URL('../src/lib/selection.ts', import.meta.url), 'utf8')
  .replace(/: \{portrait: boolean\}\[\]/, '')
  .replace(/: \{portrait: boolean\}/, '')
  .replace(/: boolean/, '')
  .replace(/\(s => s\.portrait\)/, '(s => s.portrait)');
const { canAdd } = await import('data:text/javascript,' + encodeURIComponent(src));

const L = { portrait: false };
const P = { portrait: true };

test('allows up to 2 landscape', () => {
  assert.ok(canAdd([], L));
  assert.ok(canAdd([L], L));
  assert.ok(!canAdd([L, L], L));
});
test('allows only 1 portrait', () => {
  assert.ok(canAdd([], P));
  assert.ok(!canAdd([P], P));
});
test('caps are independent', () => {
  assert.ok(canAdd([L, L], P));
  assert.ok(canAdd([P], L));
  assert.ok(!canAdd([P, L, L], L));
});
EOF
npm test 2>&1 | tail -15

